import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{B as e,c as r,f as l,q as a,D as i,N as o,g as p}from"./chunks/runtime-core.esm-bundler.C-r5b0C8.js";const g="/assets/rag._qlW0aBG.png",f=JSON.parse('{"title":"什么是RAG检索增强生成？","description":"","frontmatter":{},"headers":[],"relativePath":"column/AIFuture/基础认知/什么是RAG检索增强生成.md","filePath":"column/AIFuture/基础认知/什么是RAG检索增强生成.md","lastUpdated":1786093959000}'),d={name:"column/AIFuture/基础认知/什么是RAG检索增强生成.md"};function c(u,n,b,h,m,_){const s=e("ArticleMetadata");return l(),r("div",null,[n[0]||(n[0]=a("h1",{id:"什么是rag检索增强生成",tabindex:"-1"},[p("什么是RAG检索增强生成？ "),a("a",{class:"header-anchor",href:"#什么是rag检索增强生成","aria-label":'Permalink to "什么是RAG检索增强生成？"'},"​")],-1)),i(s),n[1]||(n[1]=o('<nav class="table-of-contents"><ul><li><a href="#📌-为什么需要-rag-解决了大模型的哪些痛点">📌 为什么需要 RAG？（解决了大模型的哪些痛点）</a></li><li><a href="#🛠️-rag-的工作原理-三步走">🛠️ RAG 的工作原理（三步走）</a><ul><li><a href="#_1-检索-retrieval">1. 检索（Retrieval）</a></li><li><a href="#_2-增强-augmentation">2. 增强（Augmentation）</a></li><li><a href="#_3-生成-generation">3. 生成（Generation）</a></li></ul></li><li><a href="#📊-rag-vs-微调-fine-tuning">📊 RAG vs 微调（Fine-tuning）</a></li><li><a href="#💡-典型应用场景">💡 典型应用场景</a></li></ul></nav><p><img src="'+g+`" alt="" loading="lazy"></p><p><strong>RAG（Retrieval-Augmented Generation，检索增强生成）</strong> 是当前大语言模型（LLM）落地应用中最核心的技术之一。</p><p>简单来说，<strong>RAG = 传统搜索/数据库检索 + 大语言模型生成</strong>。它通过在将问题提交给大模型之前，先去外部知识库中“查资料”，然后把查到的资料和你的问题一起喂给大模型，让大模型“开卷考试”，从而给出精准、有据可查的回答。</p><h2 id="📌-为什么需要-rag-解决了大模型的哪些痛点" tabindex="-1">📌 为什么需要 RAG？（解决了大模型的哪些痛点） <a class="header-anchor" href="#📌-为什么需要-rag-解决了大模型的哪些痛点" aria-label="Permalink to &quot;📌 为什么需要 RAG？（解决了大模型的哪些痛点）&quot;">​</a></h2><p>直接使用纯大语言模型（LLM）时，通常面临三个致命缺陷：</p><ol><li><strong>幻觉问题（Hallucination）</strong>：大模型本质是基于概率预测下一个词，对于不知道的知识容易“一本正经地胡说八道”。</li><li><strong>知识滞后与更新成本高</strong>：大模型的知识停留在预训练结束的那一刻。如果想补充最新知识（比如公司内部文档或最新新闻），重新训练或微调（Fine-tuning）成本高昂且耗时。</li><li><strong>数据隐私与安全性</strong>：企业内部的敏感数据（如财务报表、HR 制度）不能直接拿去训练公共大模型。</li></ol><h2 id="🛠️-rag-的工作原理-三步走" tabindex="-1">🛠️ RAG 的工作原理（三步走） <a class="header-anchor" href="#🛠️-rag-的工作原理-三步走" aria-label="Permalink to &quot;🛠️ RAG 的工作原理（三步走）&quot;">​</a></h2><p>RAG 的核心流程可以分为 <strong>检索（Retrieval）</strong>、<strong>增强（Augmentation）</strong>、<strong>生成（Generation）</strong> 三个环节：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ 用户提问 ]</span></span>
<span class="line"><span>     │</span></span>
<span class="line"><span>     ▼</span></span>
<span class="line"><span>┌─────────┐      1. 检索 (Retrieval)      ┌─────────────┐</span></span>
<span class="line"><span>│ 向量数据库 ├────────────────────────────►│ 找到的相关文档│</span></span>
<span class="line"><span>└─────────┘                               └──────┬──────┘</span></span>
<span class="line"><span>                                                 │</span></span>
<span class="line"><span>                                                 ▼</span></span>
<span class="line"><span>┌─────────┐      2. 增强 (Augmentation)    ┌─────────────┐</span></span>
<span class="line"><span>│  Prompt ├────────────────────────────►│ 带有背景知识 │</span></span>
<span class="line"><span>│ (提示词) │  (拼接：问题 + 检索到的知识)   │ 的完整提示词 │</span></span>
<span class="line"><span>└─────────┘                               └──────┬──────┘</span></span>
<span class="line"><span>                                                 │</span></span>
<span class="line"><span>                                                 ▼</span></span>
<span class="line"><span>                                           3. 生成 (Generation)</span></span>
<span class="line"><span>                                                 │</span></span>
<span class="line"><span>                                                 ▼</span></span>
<span class="line"><span>                                          [ 大模型输出回答 ]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br></div></div><h3 id="_1-检索-retrieval" tabindex="-1">1. 检索（Retrieval） <a class="header-anchor" href="#_1-检索-retrieval" aria-label="Permalink to &quot;1. 检索（Retrieval）&quot;">​</a></h3><ul><li><strong>知识库预处理</strong>：提前把公司的 PDF、Word、数据库文档切成小段（Chunk），并转化为数学向量（Vector）存入<strong>向量数据库</strong>（如 Milvus, Pinecone, Chroma 等）。</li><li><strong>匹配知识</strong>：当用户提问时，系统把问题也转为向量，去向量数据库里寻找<strong>语义最相似</strong>的几段文档片段。</li></ul><h3 id="_2-增强-augmentation" tabindex="-1">2. 增强（Augmentation） <a class="header-anchor" href="#_2-增强-augmentation" aria-label="Permalink to &quot;2. 增强（Augmentation）&quot;">​</a></h3><ul><li><strong>拼接上下文</strong>：系统将检索出来的“文档片段”和用户的“原始问题”组合成一个全新的提示词（Prompt）。</li><li><strong>格式示例</strong>：</li></ul><blockquote><p>“请根据以下参考资料回答问题。如果资料中未提及，请回答‘未知’。\\n\\n【参考资料】：……\\n\\n【用户问题】：……”</p></blockquote><h3 id="_3-生成-generation" tabindex="-1">3. 生成（Generation） <a class="header-anchor" href="#_3-生成-generation" aria-label="Permalink to &quot;3. 生成（Generation）&quot;">​</a></h3><ul><li><strong>开卷考试</strong>：大模型接收到这个带有丰富背景知识的提示词后，不再依赖“死记硬背”的记忆，而是根据传入的资料总结、提炼并生成最终答案。</li></ul><h2 id="📊-rag-vs-微调-fine-tuning" tabindex="-1">📊 RAG vs 微调（Fine-tuning） <a class="header-anchor" href="#📊-rag-vs-微调-fine-tuning" aria-label="Permalink to &quot;📊 RAG vs 微调（Fine-tuning）&quot;">​</a></h2><p>很多初学者容易混淆 RAG 和模型微调，两者的核心区别如下：</p><table tabindex="0"><thead><tr><th>对比维度</th><th>RAG（检索增强生成）</th><th>Fine-tuning（模型微调）</th></tr></thead><tbody><tr><td><strong>比喻</strong></td><td><strong>开卷考试</strong>（看资料回答）</td><td><strong>闭卷考试</strong>（把知识背进脑子里）</td></tr><tr><td><strong>知识更新</strong></td><td><strong>极快</strong>：随时往数据库添加/修改文档即可</td><td><strong>极慢/高成本</strong>：需要重新整理数据集并训练</td></tr><tr><td><strong>幻觉率</strong></td><td><strong>低</strong>：有原文可依，可要求附带引用来源</td><td><strong>中/高</strong>：依然可能产生幻觉</td></tr><tr><td><strong>数据隐私</strong></td><td><strong>极高</strong>：敏感数据留在本地向量库即可</td><td><strong>中</strong>：数据会被打包炼进权重中</td></tr><tr><td><strong>适合场景</strong></td><td>企业知识库、客服系统、最新文档/法规查询</td><td>改变模型的语言风格、特定领域术语或输出格式</td></tr></tbody></table><h2 id="💡-典型应用场景" tabindex="-1">💡 典型应用场景 <a class="header-anchor" href="#💡-典型应用场景" aria-label="Permalink to &quot;💡 典型应用场景&quot;">​</a></h2><ul><li><strong>企业内部知识库 / AI 客服</strong>：直接对接公司的 HR 手册、产品技术文档，员工/客户提问时精准回复，不漏泄机密。</li><li><strong>个人知识管理（PKM）</strong>：如 Obsidian/Notion 的 AI 插件，检索你过去记录的所有笔记并回答。</li><li><strong>专业领域法律/医疗咨询</strong>：基于最新的法律法规或医学文献提供有据可查的参考意见。</li></ul>`,22))])}const v=t(d,[["render",c]]);export{f as __pageData,v as default};
